drop policy if exists "Admins can delete media" on public.incident_media; create policy "Authorised staff can delete incident media metadata" on public.incident_media for delete to authenticated using (exists (select 1 from public.incidents i where i.id = incident_id and (public.is_super_admin((select auth.uid())) or (public.is_campus_admin((select auth.uid())) and i.campus = public.get_user_campus((select auth.uid()))))));